mapper.select:
select re.rider_evaluation_id, re.rider_base_id, re. user_id, ub.nickname as user_nickname, re.order_id, om.order_no, re.rating, re.content, re.create_time from rider_evaluation re left join user_base ub on re.user_id = ub. user_base_id left join order_main om on re.order_id = om.order_main_id
and re.rider_base_id = #{riderBaseId} and re.user_id = #{userId} and re.order_id = #{orderId} and re.rating = #{rating}
order by re.create_time desc

select re.rider_evaluation_id, re.rider_base_id, re. user_id, ub.nickname as user_nickname, re.order_id, om.order_no, re.rating, re.content, re.create_time from rider_evaluation re left join user_base ub on re. user_id = ub.user_base_id left join order_main om on re.order_id = om.order_main_id where re.rider_base_id = #{riderBaseId}
and re. rating between #{minRating} and #{maxRating}
order by re. create_time desc

mapper.update:
update rider_evaluation
rating = #{rating}, content = #{content},
where rider_evaluation_id = #{riderEvaluationId}
